    type Output = Point64;
    #[inline]
    fn sub(self, o: Point64) -> Point64 {
        Point64::new(self.x - o.x, self.y - o.y)
    }
}

impl Neg for Point64 {
    type Output = Point64;
    #[inline]
    fn neg(self) -> Point64 {
        Point64::new(-self.x, -self.y)
    }
}

/// A single contour.  `Vec<Point64>` mirrors `std::vector<Point64>`.
pub type Path64 = Vec<Point64>;
/// A list of contours.
pub type Paths64 = Vec<Path64>;

// ---------------------------------------------------------------------------
// PointD
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    #[inline]
    pub const fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }

    #[inline]
    pub fn from_64(p: Point64) -> Self {
        p.to_d()
    }

    /// Length of the vector from the origin.
    #[inline]
    pub fn length(self) -> f64 {
        (self.x * self.x + self.y * self.y).sqrt()
    }

    /// Returns the unit vector, or `(0, 0)` for a degenerate input.
    #[inline]
    pub fn normalized(self) -> PointD {
        let len = self.length();
        if len == 0.0 {
            PointD::new(0.0, 0.0)
        } else {
            PointD::new(self.x / len, self.y / len)
        }
    }

    #[inline]
    pub fn negated(self) -> PointD {
        PointD::new(-self.x, -self.y)
    }
}

impl Add for PointD {
    type Output = PointD;
    #[inline]
    fn add(self, o: PointD) -> PointD {
        PointD::new(self.x + o.x, self.y + o.y)
    }
}

impl Sub for PointD {
    type Output = PointD;
    #[inline]
    fn sub(self, o: PointD) -> PointD {
        PointD::new(self.x - o.x, self.y - o.y)
    }
}

impl Mul<f64> for PointD {
    type Output = PointD;
    #[inline]
    fn mul(self, s: f64) -> PointD {
        PointD::new(self.x * s, self.y * s)
    }
}

pub type PathD = Vec<PointD>;
pub type PathsD = Vec<PathD>;

/// `TranslatePoint(pt, dx, dy)`.
#[inline]
pub fn translate_point(pt: PointD, dx: f64, dy: f64) -> PointD {
    PointD::new(pt.x + dx, pt.y + dy)
}

/// Reflects `pt` through `pivot` (`ReflectPoint`).
#[inline]
pub fn reflect_point(pt: PointD, pivot: PointD) -> PointD {
    PointD::new(pivot.x + (pivot.x - pt.x), pivot.y + (pivot.y - pt.y))
}

// ---------------------------------------------------------------------------
// Enumerations
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum JoinType {
    Square,
    Bevel,
    Round,
    Miter,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EndType {
    Polygon,
    Joined,
    Butt,
    Square,
    Round,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    NoClip,
    Intersection,
    Union,
    Difference,
    Xor,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PointInPolygonResult {
    IsOn,
    IsInside,
    IsOutside,
}

// ---------------------------------------------------------------------------
// Rect64
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    #[inline]
    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 {
            left,
            top,
            right,
            bottom,
        }
    }

    /// An intentionally inverted rectangle, ready to be grown by `add`.
    #[inline]
    pub fn invalid() -> Self {
        Rect64::new(i64::MAX, i64::MAX, i64::MIN, i64::MIN)
    }

    #[inline]
    pub fn width(&self) -> i64 {
        self.right - self.left
    }

    #[inline]
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }

    #[inline]
    pub fn contains_point(&self, pt: Point64) -> bool {
        pt.x > self.left && pt.x < self.right && pt.y > self.top && pt.y < self.bottom
    }

    #[inline]
    pub fn add(&mut self, pt: Point64) {
        if pt.x < self.left {
            self.left = pt.x;
        }
        if pt.x > self.right {
            self.right = pt.x;
        }
        if pt.y < self.top {
            self.top = pt.y;
        }
        if pt.y > self.bottom {
            self.bottom = pt.y;
        }
    }
}

pub fn get_bounds(paths: &[Path64]) -> Rect64 {
    let mut r = Rect64::invalid();
    for path in paths {
        for &pt in path {
            r.add(pt);
        }
    }
    if r.left == i64::MAX {
        Rect64::new(0, 0, 0, 0)
    } else {
        r
    }
}

// ---------------------------------------------------------------------------
// Predicates
// ---------------------------------------------------------------------------

/// `CrossProduct(pt1, pt2, pt3)` — twice the signed area of the triangle,
/// computed in `f64` exactly as the original does.
#[inline]
pub fn cross_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.y - pt2.y) as f64)
        - ((pt2.y - pt1.y) as f64) * ((pt3.x - pt2.x) as f64)
}

/// Exact (128 bit) variant, used wherever only the *sign* matters.
#[inline]
pub fn cross_product_exact(pt1: Point64, pt2: Point64, pt3: Point64) -> i128 {
    let ax = pt2.x as i128 - pt1.x as i128;
    let ay = pt2.y as i128 - pt1.y as i128;
    let bx = pt3.x as i128 - pt2.x as i128;
    let by = pt3.y as i128 - pt2.y as i128;
    ax * by - ay * bx
}

/// Cross product of two free vectors.
#[inline]
pub fn cross_product_d(v1: PointD, v2: PointD) -> f64 {
    v1.x * v2.y - v1.y * v2.x
}

#[inline]
pub fn dot_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.x - pt2.x) as f64)
        + ((pt2.y - pt1.y) as f64) * ((pt3.y - pt2.y) as f64)
}

#[inline]
pub fn dot_product_d(v1: PointD, v2: PointD) -> f64 {
    v1.x * v2.x + v1.y * v2.y
}

/// Exact cross product of the vectors `v1 = b - a` and `v2 = d - c`.
#[inline]
pub fn cross_exact(a: Point64, b: Point64, c: Point64, d: Point64) -> i128 {
    let v1x = b.x as i128 - a.x as i128;
    let v1y = b.y as i128 - a.y as i128;
    let v2x = d.x as i128 - c.x as i128;
    let v2y = d.y as i128 - c.y as i128;
    v1x * v2y - v1y * v2x
}

/// `Area(path)` — signed area, positive for the library's "positive"
/// orientation.  Uses the same summation form as the original so that the
/// floating point result agrees bit for bit.
pub fn area(path: &[Point64]) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut prev = path[path.len() - 1];
    for &pt in path {
        a += ((prev.y + pt.y) as f64) * ((prev.x - pt.x) as f64);
        prev = pt;
    }
    a * 0.5
}

pub fn areas(paths: &[Path64]) -> f64 {
    paths.iter().map(|p| area(p)).sum()
}

/// Twice the signed area as an exact integer — safe for orientation tests.
pub fn area_exact_x2(path: &[Point64]) -> i128 {
    if path.len() < 3 {
        return 0;
    }
    let mut a: i128 = 0;
    let mut prev = path[path.len() - 1];
    for &pt in path {
        a += (prev.x as i128) * (pt.y as i128) - (pt.x as i128) * (prev.y as i128);
        prev = pt;
    }
    a
}

/// `IsPositive(path)`.
#[inline]
pub fn is_positive(path: &[Point64]) -> bool {
    area(path) >= 0.0
}

#[inline]
pub fn distance_sqr(a: Point64, b: Point64) -> f64 {
    sqr((a.x - b.x) as f64) + sqr((a.y - b.y) as f64)
}

#[inline]
pub fn distance_sqr_d(a: PointD, b: PointD) -> f64 {
    sqr(a.x - b.x) + sqr(a.y - b.y)
}

/// Squared perpendicular distance from `pt` to the infinite line
/// `line1`..`line2`.
pub fn perpendic_distance_from_line_sqrd(pt: PointD, line1: PointD, line2: PointD) -> f64 {
    let dx = line2.x - line1.x;
    let dy = line2.y - line1.y;
    if dx == 0.0 && dy == 0.0 {
        return distance_sqr_d(pt, line1);
    }
    let num = dy * (pt.x - line1.x) - dx * (pt.y - line1.y);
    (num * num) / (dx * dx + dy * dy)
}

/// True when `pt` lies on the closed segment `a`..`b`.
pub fn point_on_segment(pt: Point64, a: Point64, b: Point64) -> bool {
    if cross_product_exact(a, b, pt) != 0 {
        return false;
    }
    pt.x >= a.x.min(b.x) && pt.x <= a.x.max(b.x) && pt.y >= a.y.min(b.y) && pt.y <= a.y.max(b.y)
}

/// Even-odd point-in-polygon test with exact `IsOn` detection, matching
/// `PointInPolygon`.
pub fn point_in_polygon(pt: Point64, polygon: &[Point64]) -> PointInPolygonResult {
    if polygon.len() < 3 {
        return PointInPolygonResult::IsOutside;
    }
    let n = polygon.len();
    let mut inside = false;
    let mut j = n - 1;
    for i in 0..n {
        let pi = polygon[i];
        let pj = polygon[j];
        if point_on_segment(pt, pj, pi) {
            return PointInPolygonResult::IsOn;
        }
        // Half-open crossing rule keeps vertices from being counted twice.
        if (pi.y > pt.y) != (pj.y > pt.y) {
            // Side of the edge that `pt` falls on, computed exactly.
            let d = cross_product_exact(pi, pj, pt);
            let upward = pj.y > pi.y;
            if (d > 0) == upward {
                inside = !inside;
            }
        }
        j = i;
    }
    if inside {
        PointInPolygonResult::IsInside
    } else {
        PointInPolygonResult::IsOutside
    }
}

/// Winding number of `pt` with respect to the closed contour `polygon`.
///
/// Counter-clockwise (positive area) contours yield positive winding numbers
/// for interior points.  `pt` must not lie on the contour.
pub fn winding_number(pt: Point64, polygon: &[Point64]) -> i32 {
    let n = polygon.len();
    if n < 3 {
        return 0;
    }
    let mut wind = 0i32;
    let mut prev = polygon[n - 1];
    for &cur in polygon {
        if prev.y <= pt.y {
            if cur.y > pt.y && cross_product_exact(prev, cur, pt) > 0 {
                wind += 1;
            }
        } else if cur.y <= pt.y && cross_product_exact(prev, cur, pt) < 0 {
            wind -= 1;
        }
        prev = cur;
    }
    wind
}

/// Winding number of a floating point probe against an integer contour.
pub fn winding_number_d(pt: PointD, polygon: &[Point64]) -> i32 {
    let n = polygon.len();
    if n < 3 {
        return 0;
    }
    let mut wind = 0i32;
    let mut prev = polygon[n - 1].to_d();
    for p in polygon {
        let cur = p.to_d();
        if prev.y <= pt.y {
            if cur.y > pt.y && cross_product_d(cur - prev, pt - prev) < 0.0 {
                wind += 1;
            }
        } else if cur.y <= pt.y && cross_product_d(cur - prev, pt - prev) > 0.0 {
            wind -= 1;
        }
        prev = cur;
    }
    wind
}

// ---------------------------------------------------------------------------
// Line helpers
// ---------------------------------------------------------------------------

/// Unit normal of the edge `pt1`..`pt2`, i.e. `(dy, -dx)` normalised.
///
/// For a positively oriented (counter-clockwise) contour this points away
/// from the interior, which is why a positive delta inflates.
pub fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
    let mut dx = (pt2.x - pt1.x) as f64;
    let mut dy = (pt2.y - pt1.y) as f64;
    if dx == 0.0 && dy == 0.0 {
        return PointD::new(0.0, 0.0);
    }
    let inv_len = 1.0 / (dx * dx + dy * dy).sqrt();
    dx *= inv_len;
    dy *= inv_len;
    PointD::new(dy, -dx)
}

/// `IntersectPoint` — intersection of the two *infinite* lines through
/// `ln1a`..`ln1b` and `ln2a`..`ln2b`.  Parallel lines return `ln1b`, which is
/// what the original falls back to.
pub fn intersect_point(ln1a: PointD, ln1b: PointD, ln2a: PointD, ln2b: PointD) -> PointD {
    let dx1 = ln1b.x - ln1a.x;
    let dy1 = ln1b.y - ln1a.y;
    let dx2 = ln2b.x - ln2a.x;
    let dy2 = ln2b.y - ln2a.y;
    let det = dy1 * dx2 - dy2 * dx1;
    if det == 0.0 {
        return ln1b;
    }
    let m1 = dy1 * ln1a.x - dx1 * ln1a.y;
    let m2 = dy2 * ln2a.x - dx2 * ln2a.y;
    let x = (dx2 * m1 - dx1 * m2) / det;
    let y = (dy2 * m1 - dy1 * m2) / det;
    PointD::new(x, y)
}

/// Removes consecutive duplicate vertices (and, for closed paths, a trailing
/// vertex equal to the first).
pub fn strip_duplicates(path: &[Point64], is_closed_path: bool) -> Path64 {
    let mut out: Path64 = Vec::with_capacity(path.len());
    for &pt in path {
        if out.last().map_or(true, |&last| last != pt) {
            out.push(pt);
        }
    }
    if is_closed_path {
        while out.len() > 1 && out[out.len() - 1] == out[0] {
            out.pop();
        }
    }
    out
}

pub fn reverse_path(path: &[Point64]) -> Path64 {
    let mut p = path.to_vec();
    p.reverse();
    p
}

pub fn reverse_paths(paths: &[Path64]) -> Paths64 {
    paths.iter().map(|p| reverse_path(p)).collect()
}

