// Public acceptance battery for `clipper2::engine`.
// Build:  rustc --edition 2021 -A dead_code harness.rs -o harness && ./harness
// Every implementation must print "RESULT ok" with 0 failures.

mod clipper2;
use clipper2::*;

struct T {
    pass: u32,
    fail: u32,
}

impl T {
    fn new() -> T {
        T { pass: 0, fail: 0 }
    }
    fn check(&mut self, name: &str, cond: bool, detail: &str) {
        if cond {
            self.pass += 1;
            println!("PASS  {}", name);
        } else {
            self.fail += 1;
            println!("FAIL  {}  <<{}>>", name, detail);
        }
    }
    fn eqi(&mut self, name: &str, got: i64, want: i64) {
        self.check(name, got == want, &format!("got {} want {}", got, want));
    }
    fn eqf(&mut self, name: &str, got: f64, want: f64, tol: f64) {
        self.check(
            name,
            (got - want).abs() <= tol,
            &format!("got {} want {} tol {}", got, want, tol),
        );
    }
}

fn rect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
    // positive (area > 0) orientation
    vec![
        Point64::new(l, t),
        Point64::new(r, t),
        Point64::new(r, b),
        Point64::new(l, b),
    ]
}

fn rrect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
    reverse_path(&rect(l, t, r, b))
}

fn total_area(paths: &Paths64) -> f64 {
    areas(paths)
}

fn abs_area_sum(paths: &Paths64) -> f64 {
    paths.iter().map(|p| area(p).abs()).sum()
}

/// Structural validation shared by every case.
fn validate(t: &mut T, name: &str, sol: &Paths64, preserve_collinear: bool) {
    for (i, p) in sol.iter().enumerate() {
        t.check(
            &format!("{}/len[{}]", name, i),
            p.len() >= 3,
            &format!("contour has {} vertices", p.len()),
        );
        if p.len() < 3 {
            continue;
        }
        let n = p.len();
        let mut dup = false;
        for j in 0..n {
            if p[j] == p[(j + 1) % n] {
                dup = true;
            }
        }
        t.check(&format!("{}/nodup[{}]", name, i), !dup, "duplicate vertex");
        t.check(
            &format!("{}/nonzero[{}]", name, i),
            area(p) != 0.0,
            "zero area contour",
        );
        if !preserve_collinear {
            let mut col = false;
            for j in 0..n {
                let a = p[j];
                let b = p[(j + 1) % n];
                let c = p[(j + 2) % n];
                if cross_product_exact(a, b, c) == 0 {
                    col = true;
                }
            }
            t.check(
                &format!("{}/nocollinear[{}]", name, i),
                !col,
                "collinear vertex retained",
            );
        }
    }
    // no two output edges may properly cross
    let mut crossings = 0;
    let flat: Vec<(Point64, Point64)> = sol
        .iter()
        .flat_map(|p| {
            let n = p.len();
            (0..n).map(move |i| (p[i], p[(i + 1) % n]))
        })
        .collect();
    for i in 0..flat.len() {
        for j in (i + 1)..flat.len() {
            let (a1, a2) = flat[i];
            let (b1, b2) = flat[j];
            let d1 = cross_product_exact(a1, a2, b1).signum();
            let d2 = cross_product_exact(a1, a2, b2).signum();
            let d3 = cross_product_exact(b1, b2, a1).signum();
            let d4 = cross_product_exact(b1, b2, a2).signum();
            if d1 != 0 && d2 != 0 && d3 != 0 && d4 != 0 && d1 != d2 && d3 != d4 {
                crossings += 1;
            }
        }
    }
    t.eqi(&format!("{}/nocross", name), crossings, 0);
}

fn main() {
    let mut t = T::new();

    // 1 -- identity union of a single square
    {
        let s: Paths64 = vec![rect(0, 0, 100, 100)];
        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("01.count", sol.len() as i64, 1);
        t.eqf("01.area", total_area(&sol), 10000.0, 0.5);
        t.check("01.positive", total_area(&sol) > 0.0, "outer must be positive");
        validate(&mut t, "01", &sol, false);
    }

    // 2 -- two overlapping squares merge
    {
        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(50, 50, 150, 150)];
        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("02.count", sol.len() as i64, 1);
        t.eqf("02.area", total_area(&sol), 17500.0, 0.5);
        validate(&mut t, "02", &sol, false);
    }

    // 3 -- two disjoint squares stay separate
    {
        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(200, 200, 300, 300)];
        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("03.count", sol.len() as i64, 2);
        t.eqf("03.area", total_area(&sol), 20000.0, 0.5);
        validate(&mut t, "03", &sol, false);
    }

    // 4 -- square with a hole (reversed inner contour)
    {
        let s: Paths64 = vec![rect(0, 0, 100, 100), rrect(25, 25, 75, 75)];
        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("04.count", sol.len() as i64, 2);
        t.eqf("04.net_area", total_area(&sol), 7500.0, 0.5);
        t.eqf("04.abs_area", abs_area_sum(&sol), 12500.0, 0.5);
        let neg = sol.iter().filter(|p| area(p) < 0.0).count();
        t.eqi("04.one_hole", neg as i64, 1);
        validate(&mut t, "04", &sol, false);
    }

    // 5 -- self-intersecting bowtie, every fill rule
    {
        let bow: Path64 = vec![
            Point64::new(0, 0),
            Point64::new(100, 0),
            Point64::new(0, 100),
            Point64::new(100, 100),
        ];
        let s: Paths64 = vec![bow];

        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("05p.count", sol.len() as i64, 1);
        t.eqf("05p.area", total_area(&sol), 2500.0, 1.0);
        validate(&mut t, "05p", &sol, false);

        let sol = union_paths(&s, FillRule::Negative);
        t.eqi("05n.count", sol.len() as i64, 1);
        t.eqf("05n.abs_area", abs_area_sum(&sol), 2500.0, 1.0);
        validate(&mut t, "05n", &sol, false);

        let sol = union_paths(&s, FillRule::NonZero);
        t.eqi("05nz.count", sol.len() as i64, 2);
        t.eqf("05nz.abs_area", abs_area_sum(&sol), 5000.0, 1.0);
        validate(&mut t, "05nz", &sol, false);

        let sol = union_paths(&s, FillRule::EvenOdd);
        t.eqi("05eo.count", sol.len() as i64, 2);
        t.eqf("05eo.abs_area", abs_area_sum(&sol), 5000.0, 1.0);
        validate(&mut t, "05eo", &sol, false);
    }

    // 6 -- the same square twice: winding 2
    {
        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(0, 0, 100, 100)];
        let sol = union_paths(&s, FillRule::Positive);
        t.eqi("06p.count", sol.len() as i64, 1);
        t.eqf("06p.area", total_area(&sol), 10000.0, 0.5);
        let sol = union_paths(&s, FillRule::EvenOdd);
        t.eqi("06eo.count", sol.len() as i64, 0);
    }

    // 7/8/9 -- intersection, difference, xor
    {
        let a: Paths64 = vec![rect(0, 0, 100, 100)];
        let b: Paths64 = vec![rect(50, 50, 150, 150)];

        let sol = intersect(&a, &b, FillRule::Positive);
