// Public acceptance battery for `clipper2::offset`.
// Build:  rustc --edition 2021 -A dead_code harness.rs -o harness && ./harness
// Every implementation must print "RESULT ok" with 0 failures.

mod clipper2;
use clipper2::*;

struct T {
    pass: u32,
    fail: u32,
}

impl T {
    fn new() -> T {
        T { pass: 0, fail: 0 }
    }
    fn check(&mut self, name: &str, cond: bool, detail: &str) {
        if cond {
            self.pass += 1;
            println!("PASS  {}", name);
        } else {
            self.fail += 1;
            println!("FAIL  {}  <<{}>>", name, detail);
        }
    }
    fn eqi(&mut self, name: &str, got: i64, want: i64) {
        self.check(name, got == want, &format!("got {} want {}", got, want));
    }
    fn eqf(&mut self, name: &str, got: f64, want: f64, tol: f64) {
        self.check(
            name,
            (got - want).abs() <= tol,
            &format!("got {} want {} tol {}", got, want, tol),
        );
    }
}

fn rect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
    vec![
        Point64::new(l, t),
        Point64::new(r, t),
        Point64::new(r, b),
        Point64::new(l, b),
    ]
}

fn sq() -> Paths64 {
    vec![rect(0, 0, 100, 100)]
}

fn has(path: &Path64, x: i64, y: i64) -> bool {
    path.iter().any(|p| p.x == x && p.y == y)
}

fn inf(paths: &Paths64, d: f64, jt: JoinType, et: EndType) -> Paths64 {
    inflate_paths(paths, d, jt, et, 2.0, 0.0)
}

fn main() {
    let mut t = T::new();

    // ------------------------------------------------------------------
    // 1 -- THE case exercised by test3.cpp: square, +10, Square, Polygon
    // ------------------------------------------------------------------
    {
        let sol = inf(&sq(), 10.0, JoinType::Square, EndType::Polygon);
        t.eqi("01.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            t.eqi("01.vertices", sol[0].len() as i64, 8);
            t.eqf("01.area", area(&sol[0]), 14328.0, 1.0);
            t.check(
                "01.pt(104,-10)",
                has(&sol[0], 104, -10),
                &format!("{:?}", sol[0]),
            );
            t.check(
                "01.pt(110,-4)",
                has(&sol[0], 110, -4),
                &format!("{:?}", sol[0]),
            );
            t.check("01.pt(110,104)", has(&sol[0], 110, 104), "");
            t.check("01.pt(104,110)", has(&sol[0], 104, 110), "");
            t.check("01.pt(-4,110)", has(&sol[0], -4, 110), "");
            t.check("01.pt(-10,104)", has(&sol[0], -10, 104), "");
            t.check("01.pt(-10,-4)", has(&sol[0], -10, -4), "");
            t.check("01.pt(-4,-10)", has(&sol[0], -4, -10), "");
            t.check("01.positive", area(&sol[0]) > 0.0, "orientation preserved");
        }
    }

    // 2 -- Miter join, 90 degree corners are within the default limit of 2
    {
        let sol = inf(&sq(), 10.0, JoinType::Miter, EndType::Polygon);
        t.eqi("02.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            t.eqi("02.vertices", sol[0].len() as i64, 4);
            t.eqf("02.area", area(&sol[0]), 14400.0, 1.0);
            t.check("02.pt(-10,-10)", has(&sol[0], -10, -10), "");
            t.check("02.pt(110,110)", has(&sol[0], 110, 110), "");
        }
    }

    // 2b -- Miter with a limit below sqrt(2) must fall back to squaring
    {
        let sol = inflate_paths(&sq(), 10.0, JoinType::Miter, EndType::Polygon, 1.0, 0.0);
        t.eqi("02b.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            t.check(
                "02b.not_mitered",
                sol[0].len() > 4,
                &format!("{:?}", sol[0]),
            );
            t.check(
                "02b.area_lt_miter",
                area(&sol[0]) < 14400.0,
                &format!("area {}", area(&sol[0])),
            );
        }
    }

    // 3 -- Bevel join
    {
        let sol = inf(&sq(), 10.0, JoinType::Bevel, EndType::Polygon);
        t.eqi("03.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            t.eqi("03.vertices", sol[0].len() as i64, 8);
            t.eqf("03.area", area(&sol[0]), 14200.0, 1.0);
            t.check("03.pt(100,-10)", has(&sol[0], 100, -10), "");
            t.check("03.pt(110,0)", has(&sol[0], 110, 0), "");
            t.check("03.pt(110,100)", has(&sol[0], 110, 100), "");
            t.check("03.pt(0,-10)", has(&sol[0], 0, -10), "");
        }
