// Public acceptance battery for `clipper2::offset`.
// Build:  rustc --edition 2021 -A dead_code harness.rs -o harness && ./harness
// Every implementation must print "RESULT ok" with 0 failures.

mod clipper2;
use clipper2::*;

struct T {
    pass: u32,
    fail: u32,
}

impl T {
    fn new() -> T {
        T { pass: 0, fail: 0 }
    }
    fn check(&mut self, name: &str, cond: bool, detail: &str) {
        if cond {
            self.pass += 1;
            println!("PASS  {}", name);
        } else {
            self.fail += 1;
            println!("FAIL  {}  <<{}>>", name, detail);
        }
    }
    fn eqi(&mut self, name: &str, got: i64, want: i64) {
        self.check(name, got == want, &format!("got {} want {}", got, want));
    }
    fn eqf(&mut self, name: &str, got: f64, want: f64, tol: f64) {
        self.check(
            name,
            (got - want).abs() <= tol,
            &format!("got {} want {} tol {}", got, want, tol),
        );
    }
}

fn rect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
    vec![
        Point64::new(l, t),
        Point64::new(r, t),
        Point64::new(r, b),
        Point64::new(l, b),
    ]
}

fn sq() -> Paths64 {
    vec![rect(0, 0, 100, 100)]
}

fn has(path: &Path64, x: i64, y: i64) -> bool {
    path.iter().any(|p| p.x == x && p.y == y)
}

fn inf(paths: &Paths64, d: f64, jt: JoinType, et: EndType) -> Paths64 {
