            Point64::new(0, 100),
        ]];
        let sol = inf(&ell, 10.0, JoinType::Miter, EndType::Polygon);
        t.eqi("19.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            // L shape area 7500, grown by 10 on the outside
            t.check(
                "19.area",
                area(&sol[0]) > 10000.0 && area(&sol[0]) < 12500.0,
                &format!("area {}", area(&sol[0])),
            );
        }
        // shrinking the L must keep it in one piece and strictly smaller
        let sol = inf(&ell, -10.0, JoinType::Miter, EndType::Polygon);
        t.eqi("19b.count", sol.len() as i64, 1);
        if sol.len() == 1 {
            t.check(
                "19b.area",
                area(&sol[0]) > 3500.0 && area(&sol[0]) < 5500.0,
                &format!("area {}", area(&sol[0])),
            );
        }
    }

    // 20 -- ClipperOffset object API agrees with the free function
    {
        let mut co = ClipperOffset::new(2.0, 0.0, false, false);
        co.add_paths(&sq(), JoinType::Square, EndType::Polygon);
        let a = co.execute(10.0);
        let b = inf(&sq(), 10.0, JoinType::Square, EndType::Polygon);
        t.eqi("20.count", a.len() as i64, b.len() as i64);
        if a.len() == 1 && b.len() == 1 {
            t.eqf("20.area", area(&a[0]), area(&b[0]), 0.5);
        }
        t.check(
            "20.default_fn",
            inflate_paths_default(&sq(), 10.0, JoinType::Square, EndType::Polygon).len() == 1,
            "inflate_paths_default",
        );
    }

    println!("---");
    println!("PASSED {} FAILED {}", t.pass, t.fail);
    println!("RESULT {}", if t.fail == 0 { "ok" } else { "bad" });
}

