mkdir -p /tmp/gt && cat > /tmp/gt/gt.rs <<'EOF'
// Independent re-derivation of the Square-join offset, written from scratch
// (no shared code with the implementations under test).
fn unit_normal(p1: (f64, f64), p2: (f64, f64)) -> (f64, f64) {
    let (dx, dy) = (p2.0 - p1.0, p2.1 - p1.1);
    let l = (dx * dx + dy * dy).sqrt();
    (dy / l, -dx / l)
}
fn isect(a: (f64,f64), b: (f64,f64), c: (f64,f64), e: (f64,f64)) -> (f64,f64) {
    let den = (a.0-b.0)*(c.1-e.1) - (a.1-b.1)*(c.0-e.0);
    let t = ((a.0-c.0)*(c.1-e.1) - (a.1-c.1)*(c.0-e.0)) / den;
    (a.0 + t*(b.0-a.0), a.1 + t*(b.1-a.1))
}
fn main() {
    let sq = [(0.0,0.0), (100.0,0.0), (100.0,100.0), (0.0,100.0)];
    let d = 10.0f64;
    let n = sq.len();
    let norms: Vec<(f64,f64)> = (0..n).map(|i| unit_normal(sq[i], sq[(i+1)%n])).collect();

    let mut poly: Vec<(i64,i64)> = Vec::new();
    for j in 0..n {
        let k = (j + n - 1) % n;
        let (mut vx, mut vy) = (norms[k].0 + norms[j].0, norms[k].1 + norms[j].1);
        let l = (vx*vx + vy*vy).sqrt(); vx /= l; vy /= l;
        let q = (sq[j].0 + d*vx, sq[j].1 + d*vy);
        let p1 = (q.0 + d*vy, q.1 - d*vx);
        let p2 = (q.0 - d*vy, q.1 + d*vx);
        let p3 = (sq[k].0 + d*norms[k].0, sq[k].1 + d*norms[k].1);
        let p4 = (sq[j].0 + d*norms[k].0, sq[j].1 + d*norms[k].1);
        let pt = isect(p1, p2, p3, p4);
        let refl = (2.0*q.0 - pt.0, 2.0*q.1 - pt.1);
        println!("  corner {:?}: raw ({:.4},{:.4}) -> ({},{})   refl ({:.4},{:.4}) -> ({},{})",
            sq[j], pt.0, pt.1, pt.0.round(), pt.1.round(),
            refl.0, refl.1, refl.0.round(), refl.1.round());
        poly.push((pt.0.round() as i64, pt.1.round() as i64));
        poly.push((refl.0.round() as i64, refl.1.round() as i64));
    }
    let m = poly.len();
    let a2: i64 = (0..m).map(|i| poly[i].0*poly[(i+1)%m].1 - poly[(i+1)%m].0*poly[i].1).sum();
    println!("\nvertices = {}  {:?}", m, poly);
    println!("signed area = {}", a2 as f64 / 2.0);
    println!("bbox minus 4 corner triangles = {}", 120*120 - 4*18);

    let at = (2.0f64 + 10.0).log10() * 0.25;
    let spd = (std::f64::consts::PI / (1.0 - at/10.0).acos()).min(10.0*std::f64::consts::PI);
    println!("\nround: arc_tol={:.6} steps_per_360={:.4} circle_poly_area={:.4} (exact {:.4})",
        at, spd, 0.5*spd*100.0*(2.0*std::f64::consts::PI/spd).sin(), std::f64::consts::PI*100.0);
}
EOF
cd /tmp/gt && rustc --edition 2021 gt.rs -o gt 2>&1 | grep -E "^error" ; ./gt
